        /// <summary>
    /// Update purchase order.
    /// </summary>
    /// <param name="_purchaseOrderContract">List of contracts</param>
    /// <returns>Container of Results</returns>
    public container updatePurchaseOrder(METPurchaseOrderServiceContract _purchaseOrderContract)
    {
        METProcMetrics          procMetrics;
        procMetrics = METProcMetrics::construct(METBatchLogOperation::PurchaseOrderService);

        procMetrics.startTrace(1, strFmt("@MET:POserviceProcessing", _purchaseOrderContract.parmPurchId()));
        using (METProcMetricsScope procMetricsScope = METProcMetricsScope::constructWithErrorHandling(procMetrics))
        {

            boolean isErrorCaught;
            int infoCnt = infologLine();
            this.initParams(_purchaseOrderContract);

            changecompany(dataAreaId)
            {
                purchTable = PurchTable::find(purchaseOrderNumber, true);

                [processingStatus, processingMessage] = this.validate();
             
                if (processingStatus == METProcessingStatus::Error)
                {
                    return [processingStatus, processingMessage];
                }
                // no changes to be applied check
                if (poeDIPOAMsg == POEDIPOAMsg::AcceptedWithChanges && !isChangetobeApplied)
                {
                    return [ METProcessingStatus::Error, "@MET:Invalidchange"];
                }

                try
                {
                    ttsbegin;

                    metPurchTable = purchTable.metPurchTable();
                
                    if(!metPurchTable)
                    {
                        // check if metpurchtable does not exist then create new record.
                        metPurchTable = purchTable.metCreateMETPurchTable();
                    }
                    //add if POEDI flag exist then just update a flag.
                    if (!metPOEDIFAMsg && canUpdateASNFlag)
                    {
                        // we need to update only POASNResp flag , as per the requirement if FA message payload is coming then update the flag.
                        metPurchTable.selectForUpdate(true);
                        metPurchTable.POASNResp = updateASNFlag;
                        metPurchTable.doupdate();
                    }
                    if (metPOEDIFAMsg)
                    {
                        metPurchTable.selectForUpdate(true);
                        metPurchTable.POEDIFAMsg = NoYes::Yes;
                        if (canUpdateASNFlag)
                        {
                            metPurchTable.POASNResp = updateASNFlag;
                        }
                        metPurchTable.update();
                    }
                    else
                    {
                        if (poeDIPOAMsg == POEDIPOAMsg::AcceptedWithChanges && isChangetobeApplied)
                        {
                            this.cancelWorkflow();
                            this.processforAcceptedwithChanges();
                            this.poSubmitToWorkflow(purchTable);
                        }
                        else
                        {
                            if (poeDIPOAMsg == POEDIPOAMsg::Accepted)
                            {
                                this.cancelWorkflow();
                                this.updatePurchaseOrderHeaderAccepted();
                                this.poSubmitToWorkflow(purchTable);
                            }
                            if (poeDIPOAMsg == POEDIPOAMsg::Rejected)
                            {
                                this.cancelWorkflow();
                                this.cancelPurchaseOrder();
                                this.updateMETPurchTable();
                                this.updateReasonCodeOnRejPO(purchTable);
                                this.poSubmitToWorkflow(purchTable);
                            }
                        }
                    }
                    this.checkUpdateProcessingStatus();//success or failure required for all scenarios to call
                    ttscommit;
                }
                catch (Exception::Deadlock)
                {
                    if (appl.ttsLevel() == 0)
                    {
                        if (xSession::currentRetryCount() >= #RetryNum)
                        {
                            processingMessage = "@MET:PurchaseOrderUpdateFailedDatabaseDeadlock";
                        }
                        else
                        {
                            retry;
                        }
                    }
                    else
                    {
                        processingMessage = "@MET:PurchaseOrderUpdateFailedDatabaseDeadlock";
                    }
                    isErrorCaught = true;
                }
                catch (Exception::UpdateConflict)
                {
                    if (appl.ttsLevel() == 0)
                    {
                        if (xSession::currentRetryCount() >= #RetryNum)
                        {
                            processingMessage = "@MET:PurchaseOrderUpdateFailedDatabaseConflict";
                        }
                        else
                        {
                            retry;
                        }
                    }
                    else
                    {
                        processingMessage = "@MET:PurchaseOrderUpdateFailedDatabaseConflict";
                    }
                    isErrorCaught = true;
                }
                catch
                {
                    purchTable.reread();
                    if (poeDIPOAMsg == POEDIPOAMsg::Rejected && !purchTable.isCanceled())
                    {
                        processingMessage = "@MET:PurchaseOrderNotCancelled";
                    }
                    else
                    {
                        processingMessage = "@MET:PurchaseOrderNotUpdated";
                    }
                    isErrorCaught = true;
                    processingStatus = METProcessingStatus::Error;
                }

                if (isErrorCaught)
                {
                    container taskInfolog;
                    str       logTxt;
                    if (infologLine() > infoCnt)
                    {
                        taskInfolog = infolog.copy(infoCnt + 1, infologLine());

                        if (taskInfolog != conNull())
                        {
                            logTxt              = info::infoCon2Str(taskInfolog);
                            processingMessage  += '\n'  + logTxt;
                        }
                    }
                }

            }
            procMetrics.endTrace();
        }

            return [processingStatus, processingMessage];
        }

    public void poSubmitToWorkflow(PurchTable _purchTable)
    {
        str	comment;

        _purchTable.reread();

        if (_purchTable.DocumentState == VersioningDocumentState::Draft && _purchTable.ChangeRequestRequired)
        {
            comment = strFmt("@MET:PoSubmittedService", _purchTable.PurchId);

            if (_purchTable.checkFullyDistributedAndQualified() && _purchTable.canSubmitToWorkflow())
            {
                try
                {
                    ttsbegin;
                    _purchTable.selectForUpdate(true);
                    _purchTable.submitToWorkflow(workflowTypeStr(PurchTableTemplate), comment, false);
                    ttscommit;

                    if (_purchTable.DocumentState == VersioningDocumentState::InReview)
                    {
                        info(strFmt("@MET:POWorkflowSubmitted", _purchTable.PurchId));
                    }
                }
                catch (Exception::CLRError)
                {
                    System.Exception interopException = CLRInterop::getLastException();
                    error(strFmt("%1", interopException));
                }
                catch (Exception::Error)
                {
                    error(strFmt("@MET:POWorkFlowSubmissionFailed", _purchTable.PurchId));
                    
                    //CBNF019_Observability_POProcess
                    METTelemetryPOApprovalErrorEvent::runTelemetryEvent(_purchTable, "@MET:POWorkFlowSubmissionFailed");
                }
            }
            else
            {
                this.confirmChanges();
            }
        }
    }

        public void cancelWorkflow()
        {
            WorkflowTrackingStatusTable   WorkflowTrackingStatusTable;

            if (!cancelWorkflowflag)
            {
                cancelWorkflowflag = true;
                select CorrelationId from WorkflowTrackingStatusTable
                    where WorkflowTrackingStatusTable.TrackingStatus == WorkflowTrackingStatus::Pending
                       && WorkflowTrackingStatusTable.ContextRecId == purchTable.RecId
                        && WorkflowTrackingStatusTable.ContextTableId == purchTable.TableId;
             
                if (WorkflowTrackingStatusTable.CorrelationId)
                {
                    VersioningPurchaseOrder versioningPurchaseOrderchk;

                    if (purchTable.ChangeRequestRequired)
                    {
                        versioningPurchaseOrderchk = VersioningPurchaseOrder::newPurchaseOrder(purchTable);
                        versioningPurchaseOrderchk.cancelChangeRequest();
                    }
                }
            }
        }

        /// <summary>
        /// Update purchase order line details
        /// </summary>
        private void processPurchaseOrderLines()
        {
            if (!this.canUpdatePOLines()) // check if there are lines to be updated.
            {
                return;
            }

            listEnum     =    linesContractList.getEnumerator();
       
            while (listEnum.moveNext())
            {
                boolean lineUpdate;
                linesContract   =   listEnum.current();
                select firstonly1 forupdate purchLine 
                    where purchLine.PurchId == purchaseOrderNumber 
                        && purchLine.LineNumber == linesContract.parmLineNumber();

                metpurchline = purchline.metPurchLine();

                if(purchLine)
                { 
                    if (linesContract.parmLineAction() == METConstants::LineRejected)
                    {
                        if (purchLine.PurchStatus != PurchStatus::Canceled)
                        {
                            this.requestChange();
                            purchLine.reread();
                            PurchCancel purchCancel = purchCancel::METconstruct();
                            purchCancel.metCancelPurchLine(purchLine);
                        }
                    }
                    else
                    {
                        if (linesContract.parmPurchaseQty() != 0) //purchase qty = 0 means it does not provide any value to update.
                        {
                            if (purchLine.PurchQty != linesContract.parmPurchaseQty())
                            {
                                this.requestChange();
                                purchLine.reread();
                                purchLine.PurchQty = linesContract.parmPurchaseQty();
                                this.updateQuantities(purchLine);
                                lineUpdate = true;
                            }
                        }
                        purchLine.DeliveryDate = linesContract.parmConfirmedDeliveryDate() ? linesContract.parmConfirmedDeliveryDate():confirmedDeliveryDate;

                        if (purchLine.orig().DeliveryDate != purchLine.DeliveryDate || purchLine.orig().PurchQty != purchLine.PurchQty)
                        {
                            this.requestChange();
                            if (!lineUpdate) // this is done to reread only in case the record is not reread earlier.
                            {
                                purchLine.reread();
                            }
                            purchLine.DeliveryDate =linesContract.parmConfirmedDeliveryDate() ? linesContract.parmConfirmedDeliveryDate():confirmedDeliveryDate;
                            purchLine.update();
                        }
                    }

                    if (metpurchline.ChangeReasonCode != changeReasonCode)
                    {
                        metpurchline.selectForUpdate(true);
                        metpurchline.ChangeReasonCode = changeReasonCode;
                        metpurchline.update();
                    } 
                }
                else
                {
                    throw error (strFmt("@MET:PolineValidation",linesContract.parmLineNumber()));
                }
            }
 
        }

        /// <summary>
        /// Upate purchline quantities
        /// </summary>
        /// <param name = "_purchLine">purchline buffer</param>
        protected void updateQuantities(PurchLine _purchLine)
        {
            if (_purchLine.PurchQty != _purchLine.orig().PurchQty)
            {
                InventMovement::bufferSetTransQtyUnit(_purchLine);
            }

            PurchTableForm_DeliverySchedule     purchTableForm = new PurchTableForm_DeliverySchedule(_purchLine);
            PurchLineWritePreSuperInputContract inputContractPre = PurchLineWritePreSuperInputContract::construct();

            inputContractPre.parmPurchTable(PurchTable::find(_purchLine.PurchId));
            inputContractPre.parmPurchLine(_purchLine);
            purchTableForm.purchLine_WritePreSuper(inputContractPre);

            if (_purchLine.LineDeliveryType == LineDeliveryType::OrderLineWithMultipleDeliveries)
            {
                purchTableForm.deliveryLinesSync(_purchLine, false);
            }
            PurchLine::modifyPurchQty(_purchLine, _purchLine.inventDim(), false);// not update the price
        }

        /// <summary>
        /// Cancel purchase line
        /// </summary>
        /// <param name = "_purchLine">purchline buffer</param>
        protected void cancelLine(PurchLine     _purchLine)
        {
            /*
            PurchCancel         purchCancel = purchCancel::METconstruct();
            purchCancel.metCancelPurchLine(_purchLine);//org   commented for Original code */

            _purchLine.RemainInventPhysical = 0;
            _purchLine.RemainPurchPhysical = 0;
            _purchLine.PurchStatus = PurchStatus::Canceled;
            _purchLine.update(); 
            InventMovement::bufferSetRemainQty(_purchLine);
        }

/// <summary>
/// Confirm the purchase order changes
/// </summary>
private void confirmChanges()
{
    if (purchTable.ChangeRequestRequired)
    {
        versioningPurchaseOrder = METVersioningPurchaseOrder::newPurchaseOrder(PurchTable::find(purchTable.PurchId));
        if (purchTable.canSubmitToWorkflow())
        {
            versioningPurchaseOrder.submitChangeRequest();
            versioningPurchaseOrder.approveChangeRequest();
        }
    }
}

        /// <summary>
        /// Update the processing status.
        /// </summary>
        private void checkUpdateProcessingStatus()
        {
            purchTable.reread();

            if (processingMessage)
            {
                processingStatus = METProcessingStatus::Error;
                throw Exception::Error;
            }
            else
            {
                processingStatus = METProcessingStatus::Success;
            }
        }

/// <summary>
/// Cancel purchase order
/// </summary>
private void cancelPurchaseOrder()
{
    PurchCancel purchCancel = PurchCancel::METconstruct();
    purchCancel.parmMETPurchTable(purchTable);
    purchCancel.runOperation();
}

/// <summary>
/// Update purchase order header details
/// </summary>
private void updatePurchaseOrderHeaderAccepted()
{
    if (purchTable.DeliveryDate != confirmedDeliveryDate)
    { 
        purchTable.skipDataMethods(true);
        this.requestChange(); // ADDED REQUEST change for cchangemanagement.
        purchTable.reread();
        purchTable.DeliveryDate = confirmedDeliveryDate;
        purchTable.update();
    }
    this.updateMETPurchTable();
}

private void updateMETPurchTable()
{
    // update POEDIPOAMsg in metPurchTable with given status
    metPurchTable = purchTable.metPurchTable();
    metPurchTable.selectForUpdate(true);
    metPurchTable.POEDIPOAMsg = poeDIPOAMsg;
    metPurchTable.update();
}

/// <summary>
/// Updates reason code on rejected Purchase Order.
/// </summary>
/// <param name = "_purchTable">PurchTable/</param>
private void updateReasonCodeOnRejPO(PurchTable _purchTable)
{
    PurchLine updPurchLine;
    METPurchLine metUpdPurchLine;

    update_recordset metUpdPurchLine
        setting ChangeReasonCode = changeReasonCode
            exists join updPurchLine
                where updPurchLine.RecId == metUpdPurchLine.PurchLine
                &&    updPurchLine.PurchId == _purchTable.PurchId;
}

private void processforAcceptedwithChanges()
{
   // ttsbegin;
    if (purchTable.DeliveryDate != confirmedDeliveryDate)
    {
        this.requestChange();// call with only if request  chagen is enabled and decide what to do if workflow already started.
        purchTable.reread();
        purchTable.DeliveryDate = confirmedDeliveryDate;
        purchTable.update();
    }
    
    this.processPurchaseOrderLines();
    this.updateMETPurchTable();
   // ttscommit;
}

        /// <summary>
        /// Initialise parameters.
        /// </summary>
        /// <param name="_purchaseOrderContract">Instance of METPurchaseOrderServiceContract class</param>
        private void initParams(METPurchaseOrderServiceContract _purchaseOrderContract)
        {
            processingStatus                        = METProcessingStatus::None;
            dataAreaId                              = _purchaseOrderContract.parmDataAreaId();
            purchaseOrderNumber                     = _purchaseOrderContract.parmPurchId(); 

            if (_purchaseOrderContract.parmMETPOASN() != DefaultNoYes::Default)
            {
                canUpdateASNFlag = true;
                updateASNFlag = _purchaseOrderContract.parmMETPOASN() == DefaultNoYes::Yes ? true : false;
            }
            
            if (_purchaseOrderContract.parmPOEDIPOAMsg())
            {
                poeDIPOAMsg                             = str2Enum(poeDIPOAMsg, _purchaseOrderContract.parmPOEDIPOAMsg());
                canUpdateASNFlag = false; 
                validatePOAMsgAttribute = true;
            } 

            // added as the users are sending 1 or 0 instead of Yes or No.
            if (_purchaseOrderContract.parmMETPOEDIFAMsg() == METConstants::One)
            {
                metPOEDIFAMsg = NoYes::Yes;
            }
            else
            {
                metPOEDIFAMsg = NoYes::No;
            }
            confirmedDeliveryDate                   = _purchaseOrderContract.parmConfirmedDeliveryDate();
            linesContractList                       = _purchaseOrderContract.parmLineContract();
        }

/// <summary>
/// Update <c>PurchTable</c> only if header values are passed in the service contract.
/// </summary>
/// <returns>true if header to be updated;otherwise false.</returns>
public boolean canUpdatePOHeader()
{
    return (poeDIPOAMsg != METConstants::InvalidEnumValue);//|| (metPOEDIFAMsg != METConstants::InvalidEnumValue) || metPOYardDAppointmentStartDateTime || metPOYardDAppointmentEndDateTime || metPOYardDAppointmentID);
}

/// <summary>
/// Check if PO line details are passed in the service contract.
/// </summary>
/// <returns>true if PO line to be updated;otherwise false.</returns>
public boolean canUpdatePOLines()
{
    return linesContractList && linesContractList.elements();
}

        /// <summary>
        /// Validate parameters
        /// </summary>
        /// <returns>container</returns>
        private container validate()
        {
            if (!dataAreaId)
            {
                processingMessage = strFmt("@SYS84753", "@SYS177726");
            }
            else if (!purchaseOrderNumber)
            {
                processingMessage = strFmt("@SYS84753", "@SYS23482");
            }
            
            if (!processingMessage && !purchTable)
            {
                processingMessage = "@MET:PurchaseOrderNotFound";
            }
            if (!processingMessage && purchTable.ChangeRequestRequired)
            {
                boolean     canAffectNextYearBudgetSource;
                Ledger ledger = Ledger::findByLegalEntity(CompanyInfo::findDataArea(dataAreaId).RecId);

                canAffectNextYearBudgetSource = Ledger::isLedgerBudgetControlEnabled(ledger.RecId)
                && BudgetControlConfiguration::isSourceIntegratorEnabled(ledger.RecId, BudgetControlSourceIntegrator::PurchaseOrder)
                && LedgerFiscalCalendar::findFirstOpenPeriodInYear(ledger.FiscalCalendar, purchTable.AccountingDate).RecId == 0;
                
                if(canAffectNextYearBudgetSource && METPurchaseOrderService::IsBudgetTracked(purchTable.PurchId))
                {
                    processingMessage = "@Budget:NotAllowRequestChangeOnPODueToPeriodOnHold";
                }
            }

            if (!processingMessage && purchTable.PurchStatus == PurchStatus::Canceled)
            {
                processingMessage = "@MET:PurchaseOrderCancelled";
            }
        
            if (!processingMessage && purchTable.PurchStatus == PurchStatus::Invoiced)
            {
                processingMessage = "@MET:POAlreadyInvoiced";
            }

            if (!processingMessage && purchTable.PurchStatus == PurchStatus::Received)
            {
                processingMessage = "@MET:POAlreadyReceived";
            }
        
            if (!processingMessage && purchTable)
            {
                METVendSiteSettingsSetup metVendSiteSettingsSetup;
                select firstonly METVendSiteSettingsSetup where METVendSiteSettingsSetup.AssignedSite == purchTable.InventSiteId
                    && METVendSiteSettingsSetup.AssignedWH == purchTable.InventLocationId
                    && METVendSiteSettingsSetup.AssignedVendorAccount == purchTable.OrderAccount;

                if(!METVendSiteSettingsSetup.RecId)
                {
                    processingMessage = "@MET:VendSiteSettingErr";
                }
                else if (!METVendSiteSettingsSetup.POASetting  && validatePOAMsgAttribute)
                { 
                    processingMessage = "@MET:VendAuthPOA";
                }
                else if (!METVendSiteSettingsSetup.FASetting && metPOEDIFAMsg)
                {
                    processingMessage = "@MET:VendorFAErr";
                }
            }
         
            if (this.poeDIPOAMsg != POEDIPOAMsg::None && metPOEDIFAMsg && this.poeDIPOAMsg != METConstants::InvalidEnumValue)
            {
                processingMessage = "@MET:FAPOAErr";
            }

            //cb711 end
            if (!processingMessage && !purchTable.existPurchLine())
            {
                processingMessage = "@MET:Nopurchaselinesexist";
            }

            changeReasonCode = METPOChangeReasonCodeSetup::findPOChargeReasonCode();
            if (!changeReasonCode)
            {
                processingMessage = "@MET:POAErrorMessage";
            }
         
            if (poeDIPOAMsg == POEDIPOAMsg::AcceptedWithChanges && confirmedDeliveryDate == dateNull())
            {
                processingMessage = strFmt("@MET:ConfirmDelCheck");
            }

            if (purchTable.DeliveryDate != confirmedDeliveryDate)
            {
                // if po confirm delivery date is different than existing
                // then return false and show error.
                isChangetobeApplied = true;
            }

            //line level validation if line exist and accepted with changes.
            if (linesContractList != null && poeDIPOAMsg == POEDIPOAMsg::AcceptedWithChanges)
            {
                ListEnumerator listEnumVal    =    linesContractList.getEnumerator();
 
                while (listEnumVal.moveNext())
                {
                    linesContract   =   listEnumVal.current();
                    select firstonly1 purchLine
                    where purchLine.PurchId == purchaseOrderNumber && purchLine.LineNumber == linesContract.parmLineNumber();
             
                    if (!purchLine)
                    {
                        processingMessage = strFmt("@MET:POlineValid",linesContract.parmLineNumber(),purchaseOrderNumber);
                    }
                    else if (linesContract.parmPurchaseQty() > purchLine.PurchQty)
                    {
                        processingMessage = strFmt("@MET:POQtyValid",linesContract.parmLineNumber(),purchaseOrderNumber);
                    }

                    if (purchLine.PurchQty != linesContract.parmPurchaseQty() || purchLine.DeliveryDate != linesContract.parmConfirmedDeliveryDate()
                        || (linesContract.parmLineAction() == METConstants::LineRejected && purchLine.PurchStatus != PurchStatus::Canceled))
                    {
                        // if po line qty / confirmdelivery date is same as existing or line is already cancelled and trying to cancel again.
                        // then return false and show error.
                        isChangetobeApplied = true;
                    }
                }
            }
            
            if (processingMessage)
            {
                processingStatus = METProcessingStatus::Error;
            }

            return [processingStatus, processingMessage];
        }

/// <summary>
/// Create purchase order change request
/// </summary>
private void requestChange()
{
    if (!requestChangeFlag)
    {
        this.cancelWorkflow();
        versioningPurchaseOrder = METVersioningPurchaseOrder::newPurchaseOrder(purchTable);
        if (versioningPurchaseOrder.canChangeBeRequested())
        {
            versioningPurchaseOrder.createChangeRequest();
        }
    }
    requestChangeFlag = true;
}

        /// <summary>
        /// MPJ_23295_CustomOdataAPIPORequestChange on 12 Apr 2022 by chaminda
        /// alternate method to following
        /// BudgetSourceCollectionIntegrator::isDocumentBudgetTracked(purchTable)
        /// </summary>
        /// <param name="_purchId"> Get purchase order number</param>
        /// <returns> boolean </returns>
        public static boolean IsBudgetTracked(PurchId _purchId)
        {
            boolean     isTracked   = false;
            PurchTable  purchTable  = PurchTable::find(_purchId);
            SourceDocumentLine sourceDocumentLine = SourceDocumentLine::findBySourceDocumentHeader(purchTable.SourceDocumentHeader);
            while (!isTracked && sourceDocumentLine)
            {
                // Is there a budget being tracked?
                BudgetSourceInquiryDetails budgetDetails = BudgetSourceSourceDocumentLine::getBudgetSourceInquiryDetails(sourceDocumentLine);

                if (budgetDetails)
                {
                    while (!isTracked && budgetDetails.next())
                    {
                        isTracked = budgetDetails.currentAmountTracked() != 0;
                    }
                }

                next sourceDocumentLine;
            }

            return isTracked;
        }

        /// <summary>
        /// Service operation method to update the purchase order.
        /// </summary>
        /// <param name="_purchaseOrderContract">
        /// The instance of <c>METPurchaseOrderServiceContract</c>
        /// </param>
        /// <returns>
        /// The response <c>METPurchaseOrderContract</c>
        /// </returns>
        public METPurchaseOrderServiceResponseContract changePurchaseOrder(METPurchaseOrderServiceContract _purchaseOrderContract)
        {
            METProcessingStatus     result;
            ErrorMessage            message;

            [result, message] = this.updatePurchaseOrder(_purchaseOrderContract);

            return METPurchaseOrderServiceResponseContract::newFromParameters(result, message);
        }
